//! The generator story's driver (plan §3.2's row for `aeolus-data`:
//! "Generated by `xtask` into committed Rust (phf/trie). Also
//! generates: docs …") — the thin CLI over [`aeolus_data::codegen`]'s
//! artifact seam, in the shape the workspace's other driver already
//! established (the aeolus-cli precedent: the whole program is the
//! library `run(args, out, err) -> code`, argument list WITHOUT the
//! argv-0 program name, two sinks, exit code back).
//!
//! ```text
//! cargo xtask list                     — the committed artifact list
//! cargo xtask gen-tables               — (re)write every artifact's
//!                                        committed bytes from the rows
//! cargo xtask verify-tables            — the drift gate: regenerate and
//!                                        compare, exit 1 on ANY drift
//! cargo xtask gen-tables --check       — verify-tables' alias
//!                                        (the CI-friendly spelling)
//! ```
//!
//! Both commands take `--root <dir>` to resolve the artifacts'
//! workspace-relative paths against somewhere other than this
//! workspace (the driver tests run write mode against a temp root, so
//! a test never mutates the real tree).
//!
//! The drift discipline this enforces is the plan §8 story ("`cargo
//! xtask gen-tables` … so API drift is detectable"): the committed
//! bytes are the rows' regeneration, pinned equal in
//! `aeolus-data/tests/codegen.rs` (which runs in `cargo test` without
//! this driver) AND verifiable here in one command before a commit.

use std::path::{Path, PathBuf};

use aeolus_codegen::conformance::Conformance;
use aeolus_codegen_gpui::Caps;
use aeolus_data::codegen::{self, GeneratedArtifact};

/// The driver's usage text (the `--help` surface and the usage-error
/// suffix; the same single-source shape as the CLI's `USAGE`).
const USAGE: &str = "aeolus xtask — the committed-artifact generator\n\n\
USAGE:\n    \
cargo xtask list\n    \
cargo xtask gen-tables [--check] [--root <dir>]\n    \
cargo xtask verify-tables [--root <dir>]\n\n\
commands:\n    \
list           print every committed artifact (name + workspace path)\n    \
gen-tables     regenerate every artifact's committed bytes from the rows\n    \
verify-tables  regenerate and compare; exit 1 on any drift (the CI gate)\n\n\
flags:\n    \
--check        gen-tables: compare instead of write (the verify-tables behaviour)\n    \
--root <dir>   resolve the artifacts' workspace-relative paths against <dir>\n    \
               (default: this workspace's root)\n";

/// Exit codes: `0` clean / written, `1` drift (verify mode), `2` usage
/// error — the CLI's own code contract.
const EXIT_OK: i32 = 0;
const EXIT_DRIFT: i32 = 1;
const EXIT_USAGE: i32 = 2;

/// The default workspace root: this crate lives at `crates/xtask`, so
/// the workspace root is two directories up (compile-time constant —
/// the driver behaves the same from any working directory).
fn default_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("..").join("..")
}

/// One command outcome the driver reports per artifact — the shared
/// shape of the write and verify reports.
enum Outcome {
    /// Verify mode: the committed bytes equal the regeneration.
    Clean,
    /// Verify mode: the committed bytes differ (the gate's exit-1 case).
    Drifted,
    /// Verify mode: the file the artifact commits to is missing.
    Missing,
    /// Write mode: the regeneration replaced the committed bytes.
    Wrote(usize),
}

impl Outcome {
    /// The one-line report (the driver's whole output surface).
    fn report(&self, name: &str, path: &str) -> String {
        match self {
            Self::Clean => format!("{name}  {path}  clean\n"),
            Self::Drifted => format!("{name}  {path}  DRIFTED — run `cargo xtask gen-tables`\n"),
            Self::Missing => format!("{name}  {path}  MISSING — run `cargo xtask gen-tables`\n"),
            Self::Wrote(bytes) => format!("{name}  {path}  wrote {bytes} bytes\n"),
        }
    }
}

// ---------------------------------------------------------------------------
// The conformance page: the §5.1 score's committed artifact
// ---------------------------------------------------------------------------

/// The committed per-backend conformance page (`docs/CONFORMANCE.md`,
/// plan §5.1's "publish a per-backend conformance score") — the
/// [Conformance] report rendered from the backends' OWN capability
/// impls (`Caps`, the emit gates' own tables), so the page is the
/// emitter's verdicts, never a parallel claim. The driver extends the
/// data crate's artifact list with it (the trait lives there; the
/// render inputs live above it in the dependency graph), and the same
/// gen/verify walk pins the page's drift from then on.
struct ConformanceDocs;

impl GeneratedArtifact for ConformanceDocs {
    fn name(&self) -> &'static str {
        "conformance-docs"
    }

    fn path(&self) -> &'static str {
        "docs/CONFORMANCE.md"
    }

    fn generate(&self) -> String {
        let mut out = String::with_capacity(4096);
        out.push_str(
            "<!-- GENERATED by `cargo xtask gen-tables` from the \
`aeolus_codegen::conformance::Capability` impls (the emit gates' own capability \
tables) — DO NOT EDIT. The committed bytes are pinned by `cargo xtask \
verify-tables`; a capability edit that forgets the regeneration fails the \
gate. -->\n\n",
        );
        // The registered backends' reports, one section each. The list
        // grows with the workspace's capability impls (GPUI today — the
        // plan §3.7 matrix's first backend; the five plan-path backends
        // report through the plan bridge's typed notes instead).
        let report = Conformance::of(&Caps);
        out.push_str(&report.to_string());
        out
    }
}

/// The FULL artifact list: the data crate's registry-derived artifacts
/// plus the conformance page this driver renders from the codegen
/// crates' capability impls.
fn artifacts() -> Vec<&'static dyn GeneratedArtifact> {
    let mut list: Vec<&'static dyn GeneratedArtifact> = codegen::artifacts().to_vec();
    list.push(&ConformanceDocs);
    list
}

/// Run the driver: arguments (WITHOUT the argv-0 program name), two
/// sinks, and the process exit code back — the aeolus-cli contract.
pub fn run<I>(args: I, out: &mut dyn std::io::Write, err: &mut dyn std::io::Write) -> i32
where
    I: IntoIterator<Item = String>,
{
    let argv: Vec<String> = args.into_iter().collect();
    if argv.iter().any(|a| a == "--help" || a == "-h") {
        let _ = write!(out, "{USAGE}");
        return EXIT_OK;
    }
    let Some(cmd) = argv.first() else {
        let _ = write!(err, "{USAGE}");
        return EXIT_USAGE;
    };
    let rest = &argv[1..];

    // The shared flag parse: `--check` (gen-tables only) and `--root`.
    let mut check = false;
    let mut root: Option<String> = None;
    let mut i = 0usize;
    while i < rest.len() {
        match rest[i].as_str() {
            "--check" if cmd != "list" => check = true,
            "--root" if i + 1 < rest.len() => {
                root = Some(rest[i + 1].clone());
                i += 1;
            }
            other => {
                let _ = writeln!(err, "unexpected argument {other:?}\n{USAGE}");
                return EXIT_USAGE;
            }
        }
        i += 1;
    }
    let root = root.map_or_else(default_root, PathBuf::from);

    match cmd.as_str() {
        "list" => {
            for artifact in artifacts() {
                let _ = writeln!(out, "{}  {}", artifact.name(), artifact.path());
            }
            EXIT_OK
        }
        "gen-tables" => walk(&root, check, out),
        "verify-tables" => walk(&root, true, out),
        other => {
            let _ = writeln!(err, "unknown command {other:?}\n{USAGE}");
            EXIT_USAGE
        }
    }
}

/// Walk the artifact seam in the requested mode: verify (compare
/// against the committed bytes) or write (replace them). Any drift or
/// missing file fails verify mode with the drift exit code — the gate
/// the pre-commit story runs.
fn walk(root: &Path, check: bool, out: &mut dyn std::io::Write) -> i32 {
    let mut exit = EXIT_OK;
    let mut report = String::new();
    for artifact in artifacts() {
        let path = root.join(artifact.path());
        let generated = artifact.generate();
        let outcome = if check {
            match std::fs::read_to_string(&path) {
                Ok(committed) if committed == generated => Outcome::Clean,
                Ok(_) => Outcome::Drifted,
                Err(_) => Outcome::Missing,
            }
        } else {
            if let Some(parent) = path.parent() {
                let _ = std::fs::create_dir_all(parent);
            }
            match std::fs::write(&path, &generated) {
                Ok(()) => Outcome::Wrote(generated.len()),
                Err(io_err) => {
                    let _ = writeln!(
                        out,
                        "{}  {}  write failed: {io_err}",
                        artifact.name(),
                        artifact.path()
                    );
                    exit = EXIT_DRIFT;
                    continue;
                }
            }
        };
        report.push_str(&outcome.report(artifact.name(), artifact.path()));
        if !matches!(outcome, Outcome::Clean | Outcome::Wrote(_)) {
            exit = EXIT_DRIFT;
        }
    }
    let _ = out.write_all(report.as_bytes());
    exit
}
